import json
import sys

# Opcodes
STORE = 0
LOAD = 1
FENCE = 2
XCHG = 3


def parse_programs(request):
    progs = []
    for thread in request['threads']:
        prog = []
        for ins in thread:
            op = ins[0]
            if op == 'store':
                prog.append((STORE, ins[1], ins[2], ins[3]))
            elif op == 'load':
                prog.append((LOAD, ins[1], ins[2]))
            elif op == 'fence':
                prog.append((FENCE,))
            elif op == 'xchg':
                prog.append((XCHG, ins[1], ins[2], ins[3]))
            else:
                raise ValueError('unknown instruction: %r' % (op,))
        progs.append(tuple(prog))
    return progs


def solve(request):
    mem0 = tuple(request['memory'])
    progs = parse_programs(request)
    n = len(progs)

    # State: (memory_tuple, tuple of per-thread (pc, buffer_tuple, obs_tuple))
    # buffer_tuple holds indices of issued-but-undrained store instructions
    # of that thread, in FIFO order.
    start = (mem0, tuple((0, (), ()) for _ in range(n)))
    visited = {start}
    stack = [start]
    outcomes = set()

    while stack:
        mem, ths = stack.pop()
        terminal = True
        for t in range(n):
            pc, buf, obs = ths[t]
            prog = progs[t]
            plen = len(prog)
            if pc < plen:
                terminal = False
                ins = prog[pc]
                op = ins[0]
                if op == STORE:
                    ns = (mem, ths[:t] + ((pc + 1, buf + (pc,), obs),) + ths[t + 1:])
                    if ns not in visited:
                        visited.add(ns)
                        stack.append(ns)
                elif op == LOAD:
                    addr, width = ins[1], ins[2]
                    val = 0
                    for i in range(width):
                        b = addr + i
                        byte = -1
                        for s in reversed(buf):
                            si = prog[s]
                            sa = si[1]
                            if sa <= b < sa + si[2]:
                                byte = (si[3] >> (8 * (b - sa))) & 255
                                break
                        if byte < 0:
                            byte = mem[b]
                        val |= byte << (8 * i)
                    ns = (mem, ths[:t] + ((pc + 1, buf, obs + (val,)),) + ths[t + 1:])
                    if ns not in visited:
                        visited.add(ns)
                        stack.append(ns)
                elif op == FENCE:
                    if not buf:
                        ns = (mem, ths[:t] + ((pc + 1, buf, obs),) + ths[t + 1:])
                        if ns not in visited:
                            visited.add(ns)
                            stack.append(ns)
                else:  # XCHG, enabled only with empty buffer
                    if not buf:
                        addr, width, value = ins[1], ins[2], ins[3]
                        old = 0
                        for i in range(width):
                            old |= mem[addr + i] << (8 * i)
                        m = list(mem)
                        for i in range(width):
                            m[addr + i] = (value >> (8 * i)) & 255
                        ns = (tuple(m),
                              ths[:t] + ((pc + 1, buf, obs + (old,)),) + ths[t + 1:])
                        if ns not in visited:
                            visited.add(ns)
                            stack.append(ns)
            if buf:
                # Draining is always enabled for a nonempty buffer, even if the
                # thread has finished its instructions.
                terminal = False
                si = prog[buf[0]]
                sa, sw, sv = si[1], si[2], si[3]
                m = list(mem)
                for i in range(sw):
                    m[sa + i] = (sv >> (8 * i)) & 255
                ns = (tuple(m), ths[:t] + ((pc, buf[1:], obs),) + ths[t + 1:])
                if ns not in visited:
                    visited.add(ns)
                    stack.append(ns)
        if terminal:
            outcomes.add((tuple(o for (_, _, o) in ths), mem))

    return {
        'outcomes': [
            {'reads': [list(o) for o in obs], 'memory': list(mem)}
            for obs, mem in outcomes
        ]
    }


def main():
    write = sys.stdout.write
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        write(json.dumps(solve(json.loads(line))))
        write('\n')
        sys.stdout.flush()


if __name__ == '__main__':
    main()
