import json, random, sys
sys.path.insert(0, '/app')
from main import solve

def slow_solve(request, cap=2_000_000):
    """Independent reference: enumerate ALL execution paths (no merging)."""
    mem0 = tuple(request['memory'])
    threads = request['threads']
    outcomes = set()
    paths = [0]

    def rec(mem, ths):
        paths[0] += 1
        if paths[0] > cap:
            raise RuntimeError('path explosion')
        any_enabled = False
        for t, (pc, buf, obs) in enumerate(ths):
            prog = threads[t]
            if pc < len(prog):
                ins = prog[pc]
                op = ins[0]
                if op == 'store':
                    any_enabled = True
                    _, a, w, v = ins
                    rec(mem, ths[:t] + ((pc+1, buf+((a,w,v),), obs),) + ths[t+1:])
                elif op == 'load':
                    any_enabled = True
                    _, a, w = ins
                    val = 0
                    for i in range(w):
                        b = a + i
                        byte = mem[b]
                        for (sa, sw, sv) in reversed(buf):
                            if sa <= b < sa + sw:
                                byte = (sv >> (8*(b-sa))) & 255
                                break
                        val |= byte << (8*i)
                    rec(mem, ths[:t] + ((pc+1, buf, obs+(val,)),) + ths[t+1:])
                elif op == 'fence':
                    if not buf:
                        any_enabled = True
                        rec(mem, ths[:t] + ((pc+1, buf, obs),) + ths[t+1:])
                elif op == 'xchg':
                    if not buf:
                        any_enabled = True
                        _, a, w, v = ins
                        old = 0
                        m = list(mem)
                        for i in range(w):
                            old |= mem[a+i] << (8*i)
                            m[a+i] = (v >> (8*i)) & 255
                        rec(tuple(m), ths[:t] + ((pc+1, buf, obs+(old,)),) + ths[t+1:])
            if buf:
                any_enabled = True
                (sa, sw, sv) = buf[0]
                m = list(mem)
                for i in range(sw):
                    m[sa+i] = (sv >> (8*i)) & 255
                rec(tuple(m), ths[:t] + ((pc, buf[1:], obs),) + ths[t+1:])
        if not any_enabled:
            outcomes.add((tuple(o for (_,_,o) in ths), mem))

    rec(mem0, tuple((0, (), ()) for _ in threads))
    return {'outcomes': [{'reads': [list(o) for o in obs], 'memory': list(m)}
                         for obs, m in outcomes]}

def key(resp):
    return sorted(json.dumps({'reads': o['reads'], 'memory': o['memory']},
                             sort_keys=True) for o in resp['outcomes'])

def rand_req(rng):
    nthreads = rng.randint(1, 3)
    memsize = rng.randint(1, 8)
    mem = [rng.randint(0, 255) for _ in range(memsize)]
    budget = min(10, rng.randint(1, 7))  # keep small for slow solver
    threads = []
    for _ in range(nthreads):
        k = rng.randint(0, min(4, budget))
        budget -= k
        prog = []
        for _ in range(k):
            w = rng.choice([1, 2, 4])
            a = rng.randint(0, memsize - w) if memsize >= w else None
            ops = ['store', 'load', 'fence', 'xchg'] if a is not None else ['fence']
            op = rng.choice(ops)
            if op == 'store':
                prog.append(['store', a, w, rng.randint(0, (1 << (8*w)) - 1)])
            elif op == 'load':
                prog.append(['load', a, w])
            elif op == 'xchg':
                prog.append(['xchg', a, w, rng.randint(0, (1 << (8*w)) - 1)])
            else:
                prog.append(['fence'])
        threads.append(prog)
    return {'memory': mem, 'threads': threads}

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 500
    rng = random.Random(seed)
    for i in range(count):
        req = rand_req(rng)
        try:
            fast = solve(req)
            slow = slow_solve(req)
        except RuntimeError:
            continue
        if key(fast) != key(slow):
            print('MISMATCH on case', i)
            print(json.dumps(req))
            print('fast:', key(fast))
            print('slow:', key(slow))
            return 1
        # duplicates check
        outs = fast['outcomes']
        ks = [json.dumps({'reads': o['reads'], 'memory': o['memory']}, sort_keys=True) for o in outs]
        assert len(ks) == len(set(ks)), 'duplicate outcomes!'
    print('OK', count, 'cases (seed %d)' % seed)
    return 0

if __name__ == '__main__':
    sys.exit(main())
